import pathlib,tempfile,json,base64,subprocess,sys,hashlib
files={'retain-older-inputs.py': '', 'archive-retention-plan.json': '', 'retention.test.py': '', 'mount-order.test.py': '', 'resume95/native95-host-controls.py': '', 'resume95/native95-controls.test.py': '', 'resume95/native95-pins.json': '', 'packet.json': ''}
with tempfile.TemporaryDirectory(prefix='keel-independent-mount8ee-')as d:
 root=pathlib.Path(d)
 for n,b in files.items():
  p=root/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))
 p=root/'resume95/native95-pins.json';pins=json.loads(p.read_bytes());pins['packetPath']=str(root/'packet.json');p.write_text(json.dumps(pins))
